#!/bin/bash
# Generated By: Claude Code (deepseek-ai/DeepSeek-V4.1-Flash-1017)
#
# /sandbox/.env has exactly two sources:
#   1. exported OPENSHELL_SANDBOX_<NAME> on the host, written as <NAME>
#   2. the OTEL identity/query block sandbox.sh derives per sandbox
#
# Everything else is gone. This test pins the parts that are easy to regress:
# the prefix is required and stripped, only exported names travel, a plain host
# variable is never captured by name, a non-prefixed variable never ships, and
# the OTEL block and generated SANDBOX_* identity survive.
#
# Run: tests/test-sandbox-env.sh

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"

TMP="$(mktemp -d)"
# shellcheck disable=SC1091 # tests/isolate.sh: fail-closed fakes, scratch HOME
source "$(dirname "${BASH_SOURCE[0]}")/isolate.sh"
trap 'rm -rf "$TMP"' EXIT

WORK="${TMP}/work"
mkdir -p "$WORK"
cp -r "${REPO_ROOT}/scripts" "${REPO_ROOT}/config" "${REPO_ROOT}/policies" "$WORK/"
printf 'OTEL_URL=http://x:4318\nPROMETHEUS_URL=http://x:9090\nLOKI_URL=http://x:3100\n' \
    > "${WORK}/config/site.env"

fail=0
# A clean env so a host that already exports OPENSHELL_SANDBOX_* or plain
# credentials cannot change the result. PATH carries the test's fakes.
run_create() {
    local profile="$1"
    env -i PATH="$PATH" HOME="$TMP/home" \
        OPENSHELL_SANDBOX_DEMO_OVERRIDE=probe \
        SANDBOX_PLAIN_MARKER=plain \
        SANDBOX_CLONE_SINCE=-3months \
        bash -c '
            OPENSHELL_SANDBOX_UNEXPORTED=local   # not exported: must not ship
            exec "$1" --create probe-env --profile "$2" \
                --no-clone --no-connect --dryrun
        ' _ "${WORK}/scripts/sandbox.sh" "$profile" 2>&1
}

work_out="$(run_create work)" || true
grep -q -- '--- .env content' <<<"$work_out" \
    || { echo "FAIL: work --dryrun printed no .env block" >&2; fail=1; }
grep -qx 'DEMO_OVERRIDE=probe' <<<"$work_out" \
    || { echo "FAIL: exported OPENSHELL_SANDBOX_ var did not reach .env stripped" >&2; fail=1; }
grep -q 'OPENSHELL_SANDBOX_DEMO_OVERRIDE' <<<"$work_out" \
    && { echo "FAIL: OPENSHELL_SANDBOX_ prefix survived into .env" >&2; fail=1; }
grep -q 'UNEXPORTED' <<<"$work_out" \
    && { echo "FAIL: an unexported OPENSHELL_SANDBOX_ variable shipped" >&2; fail=1; }
grep -q '^PLAIN_MARKER=\|^SANDBOX_PLAIN_MARKER=' <<<"$work_out" \
    && { echo "FAIL: a non-prefixed variable shipped" >&2; fail=1; }
grep -q '^CLONE_SINCE=' <<<"$work_out" \
    && { echo "FAIL: a host-only SANDBOX_ knob shipped stripped" >&2; fail=1; }

# The OTEL exception and generated identity keep their automatic values.
grep -q '^OTEL_EXPORTER_OTLP_ENDPOINT=http://x:4318$' <<<"$work_out" \
    || { echo "FAIL: OTEL endpoint missing from .env" >&2; fail=1; }
grep -q '^OTEL_RESOURCE_ATTRIBUTES=' <<<"$work_out" \
    || { echo "FAIL: OTEL identity missing from .env" >&2; fail=1; }
grep -qx 'SANDBOX_PROFILE=work' <<<"$work_out" \
    || { echo "FAIL: generated SANDBOX_PROFILE missing" >&2; fail=1; }

# Values that used to be patched in are gone unless exported prefixed.
grep -q '^CLAUDE_DASHBOARD_HOST=\|^REVIEW_ORCHESTRATOR_' <<<"$work_out" \
    && { echo "FAIL: a removed hard-coded env var came back" >&2; fail=1; }

# The prefix is not profile-filtered: which credential a sandbox carries is the
# operator's call.
personal_out="$(run_create personal)" || true
grep -qx 'DEMO_OVERRIDE=probe' <<<"$personal_out" \
    || { echo "FAIL: personal profile dropped the operator's export" >&2; fail=1; }
grep -qx 'SANDBOX_PROFILE=personal' <<<"$personal_out" \
    || { echo "FAIL: generated SANDBOX_PROFILE missing on personal" >&2; fail=1; }

[[ $fail -eq 0 ]] && echo "all sandbox-env checks passed"
exit $fail
